using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectEnvironment;
public sealed class WireSchemeForm:Form{readonly AppSettings s=SettingsService.Load();readonly string active;EnvRules? rules;readonly List<RadioButton> radios=new();
 readonly TextBox projectBox=new(){Dock=DockStyle.Fill};readonly Label markerLabel=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true,ForeColor=Color.FromArgb(80,80,80)};readonly FlowLayoutPanel list=new(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};
 readonly CheckBox drawingsBox=new(){Text="Write every drawing's WD_M too (open drawings are changed in the session and need saving; needed for the numbering to change in existing sheets)",AutoSize=true,Anchor=AnchorStyles.Left};readonly CheckBox wiresBox=new(){Text="Trace wires: write From/To numbers or un-fix the old ones",AutoSize=true,Anchor=AnchorStyles.Left};readonly CheckBox retagBox=new(){Text="Queue Insert Wire Numbers (retag) in AutoCAD Electrical afterwards",AutoSize=true,Anchor=AnchorStyles.Left};
 readonly Label status=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};readonly Button previewButton=new(){Text="Preview...",Dock=DockStyle.Fill};readonly Button applyButton=new(){Text="Switch",Dock=DockStyle.Fill};readonly Button closeButton=new(){Text="Close",Dock=DockStyle.Fill};readonly Button helpButton=new(){Text="Help",Dock=DockStyle.Fill};readonly ToolTip tips=new(){AutoPopDelay=30000,InitialDelay=300,ReshowDelay=100};
 public string? ReloadProjectPath{get;private set;} public bool RetagRequested{get;private set;}
 public WireSchemeForm(string start,string activeProject){active=activeProject;Text=BuildInfo.Title("switch wire-number scheme");StartPosition=FormStartPosition.CenterParent;Size=new Size(900,620);MinimumSize=new Size(720,480);projectBox.Text=start;drawingsBox.Checked=s.ApplyToDrawings;wiresBox.Checked=s.ComputeFromTo;retagBox.Checked=s.RetagAfterApply;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=7,Padding=new Padding(10)};root.ColumnStyles.Add(new(SizeType.Absolute,110));root.ColumnStyles.Add(new(SizeType.Percent,100));root.ColumnStyles.Add(new(SizeType.Absolute,110));foreach(int h in new[]{34,30,0,30,30,30,44})root.RowStyles.Add(h==0?new(SizeType.Percent,100):new(SizeType.Absolute,h));
  root.Controls.Add(new Label{Text="Project (.wdp)",AutoSize=true,Anchor=AnchorStyles.Left},0,0);root.Controls.Add(projectBox,1,0);var browse=new Button{Text="Browse...",Dock=DockStyle.Fill};browse.Click+=(_,_)=>{using var d=new OpenFileDialog{Filter="AutoCAD Electrical project (*.wdp)|*.wdp",FileName=projectBox.Text};if(d.ShowDialog(this)==DialogResult.OK){projectBox.Text=d.FileName;ShowMarker();}};root.Controls.Add(browse,2,0);
  root.Controls.Add(markerLabel,1,1);root.SetColumnSpan(markerLabel,2);root.Controls.Add(new Label{Text="Scheme",AutoSize=true,Anchor=AnchorStyles.Left|AnchorStyles.Top},0,2);root.Controls.Add(list,1,2);root.SetColumnSpan(list,2);
  root.Controls.Add(drawingsBox,1,3);root.SetColumnSpan(drawingsBox,2);root.Controls.Add(wiresBox,1,4);root.SetColumnSpan(wiresBox,2);root.Controls.Add(retagBox,1,5);root.SetColumnSpan(retagBox,2);
  var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=5};footer.ColumnStyles.Add(new(SizeType.Percent,100));footer.ColumnStyles.Add(new(SizeType.Absolute,110));footer.ColumnStyles.Add(new(SizeType.Absolute,110));footer.ColumnStyles.Add(new(SizeType.Absolute,100));footer.ColumnStyles.Add(new(SizeType.Absolute,100));footer.Controls.Add(status,0,0);footer.Controls.Add(previewButton,1,0);footer.Controls.Add(applyButton,2,0);footer.Controls.Add(helpButton,3,0);footer.Controls.Add(closeButton,4,0);root.Controls.Add(footer,0,6);root.SetColumnSpan(footer,3);Controls.Add(root);
  previewButton.Click+=(_,_)=>Run(false);applyButton.Click+=(_,_)=>Run(true);closeButton.Click+=(_,_)=>Close();helpButton.Click+=(_,_)=>{using var f=new TextReportForm("LSE_Env: wire scheme help",HelpText.Fix(HelpText.WireScheme));f.ShowDialog(this);};
  tips.SetToolTip(projectBox,"The AutoCAD Electrical project (.wdp) to change.");tips.SetToolTip(browse,"Pick a project .wdp file.");tips.SetToolTip(list,"Pick how wires should be numbered. The grey text under each scheme says what it does.");tips.SetToolTip(drawingsBox,"Also write each drawing's WD_M numbering settings. Without it existing sheets keep their old settings. Open drawings are changed in the session; you must save them.");tips.SetToolTip(wiresBox,"Follow the wires to write From/To numbers, or to un-fix them when going back to another scheme.");tips.SetToolTip(retagBox,"When this window closes, start AutoCAD Electrical's Insert Wire Numbers so sequential numbers are renumbered.");tips.SetToolTip(previewButton,"Show what would change as text. Nothing is written.");tips.SetToolTip(applyButton,"Switch the project to the chosen scheme. Every file is backed up first, each change is checked afterwards, and everything is rolled back if one fails.");tips.SetToolTip(helpButton,"A guide to this window: the steps, the tick boxes, what each scheme means and a worked example.");tips.SetToolTip(closeButton,"Close this window.");
  AcceptButton=applyButton;CancelButton=closeButton;
  Shown+=(_,_)=>{try{rules=RulesService.Load(s.RulesConfigPath);foreach(var w in rules.WireSchemes){var rb=new RadioButton{AutoSize=true,Tag=w,Text=w.Name+(w.IsFromTo?"   [From/To, fixed numbers]":w.FromTemplate?"   [values from the LSE template]":""),Font=new Font("Segoe UI",9.5f,FontStyle.Bold),Margin=new Padding(4,8,4,0)};rb.CheckedChanged+=(_,_)=>wiresBox.Enabled=true;radios.Add(rb);list.Controls.Add(rb);list.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(720,0),Text=w.Description+(w.Values.Count>0?"   ("+string.Join(", ",w.Values.Select(v=>v.Key+"="+v.Value))+")":""),Margin=new Padding(28,0,4,4),ForeColor=Color.FromArgb(70,70,70)});}
   var last=radios.FirstOrDefault(r=>((WireScheme)r.Tag!).Name.Equals(s.LastScheme,StringComparison.OrdinalIgnoreCase))??radios.FirstOrDefault();if(last is not null)last.Checked=true;ShowMarker();status.Text=radios.Count==0?"The rules JSON defines no wire schemes.":"Pick a scheme and press Switch. Preview shows the changes without writing.";}catch(Exception ex){status.Text="Rules could not be loaded: "+ex.Message;ErrorService.Show(this,"Loading rules",ex);applyButton.Enabled=false;previewButton.Enabled=false;}};}
 WireScheme? Selected=>radios.FirstOrDefault(r=>r.Checked)?.Tag as WireScheme;
 void ShowMarker(){var m=File.Exists(projectBox.Text.Trim())?MarkerService.Read(projectBox.Text.Trim()):null;markerLabel.Text=m is null?(projectBox.Text.Trim().Length==0?"No project selected.":"No LSE_Env profile on record for this project yet."):$"On record: {m.Scheme} (profile {m.Profile}) applied {m.Applied:yyyy-MM-dd HH:mm} by {m.By}{(m.FromTo?"  [From/To numbers were written as fixed]":"")}";}
 void Run(bool apply){try{var scheme=Selected;if(scheme is null)throw new InvalidOperationException("Pick a wire scheme first.");string wdp=projectBox.Text.Trim();if(!File.Exists(wdp))throw new FileNotFoundException("Project file was not found.",wdp);var r=rules!;var bridge=AcadeBridgeService.Bridge(r);
   UseWaitCursor=true;applyButton.Enabled=false;previewButton.Enabled=false;try{var st=EnvironmentService.ReadProject(wdp,r,bridge,drawingsBox.Checked||wiresBox.Checked,m=>Status(m));var plan=EnvironmentService.Plan(st,null,scheme,r,s,bridge,drawingsBox.Checked,wiresBox.Checked,m=>Status(m));
    if(!apply){using var f=new TextReportForm("LSE_Env preview: "+scheme.Name,EnvironmentService.Render(plan));f.ShowDialog(this);Status("Preview shown; nothing written.");return;}
    if(plan.Applicable==0){string why=EnvironmentService.NothingToApply(plan);MessageBox.Show(why+Environment.NewLine+Environment.NewLine+string.Join(Environment.NewLine,plan.Changes.Where(c=>!c.Applies).Select(c=>c.Item+": "+c.Note).Take(12)),"LSE_Env");Status(why.Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)[0].Trim());return;}
    int wd=plan.Changes.Count(c=>c.Selected&&c.Kind==ChangeKind.SetWdm);int wires=plan.Changes.Count(c=>c.Selected&&c.Kind==ChangeKind.WireNumbers);int unfix=plan.Changes.Count(c=>c.Selected&&c.Kind==ChangeKind.UnfixWireNumbers);int wdp2=plan.Changes.Count(c=>c.Selected&&c.Target=="wdp");
    string msg=$"Switch {st.ProjectName} to '{scheme.Name}'?\n\n{wdp2} project line(s), {wd} WD_M value(s) in {plan.Changes.Where(c=>c.Selected&&c.Kind==ChangeKind.SetWdm).Select(c=>c.Target).Distinct(StringComparer.OrdinalIgnoreCase).Count()} drawing(s), From/To numbering in {wires} drawing(s), un-fix in {unfix} drawing(s).\n\nEvery touched file is backed up first.{(retagBox.Checked?"\nInsert Wire Numbers will be queued afterwards.":"")}";
    if(MessageBox.Show(msg,"LSE_Env",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK){Status("Cancelled.");return;}
    var res=ApplyService.Execute(plan,s,bridge,m=>Status(m));s.LastScheme=scheme.Name;try{SettingsService.Save(s);}catch{}
    if(s.ReactivateAfterApply&&active.Length>0&&active.Equals(st.WdpPath,StringComparison.OrdinalIgnoreCase))ReloadProjectPath=st.WdpPath;RetagRequested=retagBox.Checked;ShowMarker();
    if(s.ShowReportAfterApply){using var f=new TextReportForm("LSE_Env result: "+scheme.Name,res.Report);f.ShowDialog(this);}Status(res.Unresolved.Count==0?$"Switched to {scheme.Name}: {res.Applied} change(s) applied and verified. Backup in {res.BackupFolder}":$"Switched with {res.Unresolved.Count} unverified change(s); see the report.");}
   finally{UseWaitCursor=false;applyButton.Enabled=true;previewButton.Enabled=true;}}
  catch(Exception ex){Status("Failed: "+ex.Message.Split('\n')[0]);ErrorService.Show(this,"Switch wire scheme",ex);}}
 void Status(string m){status.Text=m;status.Refresh();}
}
